{
  "header": {
    "version": "1.0.0",
    "committed_on": "2026-02-01",
    "post_hoc": false,
    "change_log": [{"version": "1.0.0", "date": "2026-02-01", "reason": "initial contract, committed before any qualifying month-end"}]
  },
  "trigger": {"metric": "net_mrr", "provider": "stripe_billing", "report_name": "Stripe Billing MRR report", "currency": "USD", "threshold": 4000, "consecutive_month_ends": 3},
  "runway_co_condition": {"min_months": 12, "savings": 40600, "monthly_burn": 3100, "burn_includes": ["living_costs", "self_employment_tax", "health_insurance", "business_costs"], "computed_on": "2026-08-31", "months": 13.1},
  "gates": {"max_single_customer_share": 0.2, "max_gross_mrr_churn_monthly": 0.05},
  "reversal": {"mrr_below": 3000, "consecutive_month_ends": 2, "runway_below_months": 6},
  "conclusion": {
    "statement": "Resign effective the first of the month after the third consecutive month-end at or above 4,000 USD net MRR with runway at or above 12 months and both gates inside their limits; give 30 days notice; tell my partner first, then my manager, then customers.",
    "action": "resign",
    "date_rule": "effective the first of the month after the third qualifying month-end",
    "notice_period_days": 30,
    "inform_order": ["partner", "manager", "customers"],
    "evidence_links": [
      {"url": "https://dashboard.stripe.com/billing/reports/mrr", "kind": "provider_mrr_report", "covers_month_end": "2026-08-31"},
      {"url": "repo:finance/runway-model-2026-Q3.xlsx", "kind": "runway_model", "covers_month_end": "2026-08-31"}
    ]
  },
  "review": {
    "cadence": "quarterly",
    "last_run_at": "2026-09-01",
    "entries": [
      {"run_at": "2026-06-01", "readings": [{"month_end": "2026-03-31", "net_mrr": 3480}, {"month_end": "2026-04-30", "net_mrr": 3720}, {"month_end": "2026-05-31", "net_mrr": 3910}], "runway_months": 12.4, "top_customer_share": 0.12, "gross_churn_monthly": 0.031, "verdict": "not_fired"},
      {"run_at": "2026-09-01", "readings": [{"month_end": "2026-06-30", "net_mrr": 4150}, {"month_end": "2026-07-31", "net_mrr": 4300}, {"month_end": "2026-08-31", "net_mrr": 4420}], "runway_months": 13.1, "top_customer_share": 0.11, "gross_churn_monthly": 0.028, "verdict": "fired"}
    ]
  }
}

{
  "header": {
    "version": "1.0.0",
    "committed_on": "2026-07-03",
    "post_hoc": false,
    "change_log": [{"version": "1.0.0", "date": "2026-07-03", "reason": "wrote it up after the big month"}]
  },
  "trigger": {"metric": "gross_cash", "provider": "spreadsheet", "report_name": "my sheet", "currency": "USD", "threshold": 4000, "consecutive_month_ends": 1},
  "runway_co_condition": {"min_months": 12, "savings": 18000, "monthly_burn": 1500, "burn_includes": ["living_costs"], "computed_on": "2026-07-03", "months": 12},
  "gates": {"max_single_customer_share": 1, "max_gross_mrr_churn_monthly": 1},
  "reversal": {"mrr_below": 4000, "consecutive_month_ends": 1, "runway_below_months": 0},
  "conclusion": {
    "statement": "Quit when ready.",
    "action": "resign",
    "date_rule": "soon",
    "notice_period_days": 0,
    "inform_order": [],
    "evidence_links": [{"url": "screenshot.png", "kind": "spreadsheet_screenshot", "covers_month_end": "2026-06-30"}]
  },
  "review": {
    "cadence": "quarterly",
    "last_run_at": "2026-09-01",
    "entries": [
      {"run_at": "2026-09-01", "readings": [], "runway_months": 12, "top_customer_share": 0.71, "gross_churn_monthly": 0.09, "verdict": "fired"}
    ]
  }
}
